steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issueLabels(first: 100) {
        nodes {
          id
          name
          group
          color
        }
      }
      issue(identifier: \"MOB-3\") {
        id
        identifier
        title
        labels {
          nodes {
            id
            name
            group
          }
        }
      }
    }"
  }'
